const { test, expect } = require('@playwright/test');
for (let i = 0; i < 12; i += 1) test('DEMO-9/TC-9' + String(i).padStart(2, '0') + ': filler ' + i, async ({ request }) => { expect((await request.get('/health')).status()).toBe(200); });
test('DEMO-1/TC-001: health is ok', async ({ request }) => { expect((await request.get('/health')).status()).toBe(200); });
test('DEMO-1/TC-002: the cart total is 11', async ({ request }) => { const r = await (await request.get('/api/total')).json(); expect(r.total).toBe(11); });
test('DEMO-1/TC-003: the reports service answers 200', async ({ request }) => { expect((await request.get('/api/unavailable')).status()).toBe(200); });
test('DEMO-1/TC-004: the secure endpoint is reachable', async ({ request }) => { expect((await request.get('/api/secure')).status()).toBe(200); });
test('DEMO-1/TC-005: the archive page exists', async ({ request }) => { expect((await request.get('/api/missing')).status()).toBe(200); });
test('DEMO-1/TC-006: the payment service is reachable', async ({ request }) => { expect((await request.get('http://127.0.0.1:9/pay')).status()).toBe(200); });
test('DEMO-1/TC-007: the helper formats a price', async () => { const fmt = undefined; expect(fmt(5)).toBe('$5.00'); });
test('DEMO-1/TC-008: the slow report finishes', async ({ request }) => { expect((await request.get('/api/slow', { timeout: 1500 })).status()).toBe(200); });
